// ADR-013: create the non-payroll ERPNext HR worker for an onboarded external collaborator, then
// bind the HR-EMP id back into IAM. n8n is the only ERPNext writer (ADR-009). Uses this.helpers.httpRequest
// (robust vs templated HTTP nodes). ERPNext gender/DOB made non-mandatory for externals; DOJ = today.
const ev = $input.first().json.body || $input.first().json;
const auth = 'token ' + $env.ERPNEXT_API_KEY + ':' + $env.ERPNEXT_API_SECRET;
const H = { Authorization: auth, 'content-type': 'application/json' };
const emp = await this.helpers.httpRequest({ method:'POST', url:'https://erp.devandre.sbs/api/resource/Employee', headers:H, body:{ first_name: ev.displayName, employment_type: ev.engagementType, company:'Ktayl Solutions', status:'Active', date_of_joining: new Date().toISOString().slice(0,10), custom_agency_or_firm: ev.firm||'', custom_iam_collaborator_id: ev.idempotencyKey }, json:true, skipSslCertificateValidation:true });
const hrName = emp.data.name;
await this.helpers.httpRequest({ method:'POST', url:'https://iam-dev.10.0.0.200.nip.io/api/collaborators/' + ev.collaboratorId + '/hr-worker-ref', headers:{ 'X-IAM-Service-Key': $env.IAM_SERVICE_KEY, 'content-type':'application/json' }, body:{ hrWorkerRef: hrName }, json:true, skipSslCertificateValidation:true });
return [{ json: { ok:true, hrWorkerRef: hrName, collaboratorId: ev.collaboratorId } }];
